CREATE TABLE `ai_heart_wallets` (`user_id` VARCHAR(191) NOT NULL, `hearts` INTEGER NOT NULL DEFAULT 0, `credits` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`user_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ai_heart_games` (`id` VARCHAR(191) NOT NULL, `user_id` VARCHAR(191) NOT NULL, `kinds` JSON NOT NULL, `clicks` JSON NOT NULL, `score` INTEGER NOT NULL DEFAULT 0, `status` VARCHAR(20) NOT NULL DEFAULT 'ready', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `started_at` DATETIME(3) NULL, `ended_at` DATETIME(3) NULL, `converted` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `ai_heart_games_user_id_status_idx` (`user_id`,`status`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ai_heart_uses` (`id` VARCHAR(191) NOT NULL, `user_id` VARCHAR(191) NOT NULL, `status` VARCHAR(20) NOT NULL DEFAULT 'reserved', PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
